-- c001-v001: Yahuda İsa'nın Mesih'in kulu kardeşi –ve Yakub'un –lara –de Tanrı Baba'da sevilmiş–olanlara ve İsa Mesih'te korunmuş–olanlara çağrılmışlara
-- c001-v002: merhamet size ve esenlik ve sevgi çoğalsın
-- c001-v003: Sevgililer her gayreti göstererek yazmaya size hakkında – ortak bizim kurtuluşumuz zorunluluğu buldum yazmak size yalvararak uğraşmanızı – bir–kez teslim–edilmiş –lara kutsallara iman–için
-- c001-v004: sızdılar çünkü bazı insanlar – eskiden önceden–yazılmış –e bu – yargıya tanrısızlar – –nın Tanrı'nın bizim lütfunu değiştirenler –e ahlaksızlığa ve – tek Efendi'yi ve Rab bizim İsa'yı Mesih'i inkar–edenler
-- c001-v005: Hatırlatmak –ise size istiyorum bilenlere siz bir–kez her–şeyi ki – Rab halkı –den ülkesinden Mısır'ın kurtardıktan–sonra – ikinci–kez – – inanmayanları yok–etti
-- c001-v006: melekleri –ve – – korumamış–olanları – kendi yetkilerini ama terk–edenleri – kendine–ait konutlarını –e yargı–için büyük günün zincirlerle ebedi altında karanlığın sakladı
-- c001-v007: nasıl Sodom ve Gomora ve – çevresindeki onların şehirler – benzer şekilde bunlara fuhuş–yaparak ve gidip ardından bedenin başka sergilenmektedirler örnek–olarak ateşin ebedi cezasına maruz–kalarak
-- c001-v008: Benzer–şekilde gerçekten da bunlar rüya–görenler bedeni –bir–yandan kirletirler egemenliği –öte–yandan reddederler yüceliklere –ve küfrederler
-- c001-v009: – –ise Mikael – başmelek ne–zaman – İblis'le tartışarak konuşuyordu hakkında – Musa'nın bedenini – cesaret–edemedi yargı getirmeye küfrün ama dedi Azarlasın seni Rab
-- c001-v010: bunlar –ise ne–kadar –bir–yandan – bilmezler küfrederler ne–kadar –öte–yandan doğal–olarak gibi – akılsız hayvanlar anlarlar –de bunlarda mahvolurlar
-- c001-v011: vay onlara çünkü – yolunda – Kayin'in yürüdüler ve – aldanışına – Balam'ın ücret–için akıttılar ve – isyanında – Korah'ın yok–oldular
-- c001-v012: Bunlar –dırlar – –deki – sevgi–şölenlerinizde sizin lekeler birlikte–yiyip–içenler korkusuzca kendilerini güdenler bulutlar susuz –ile rüzgarlar sürüklenen ağaçlar sonbahar meyvesiz iki–kez ölmüş kökünden–sökülmüş
-- c001-v013: dalgalar vahşi denizin köpürten – kendi utançlarını yıldızlar başıboş –için – karanlığı – zifirin –e sonsuza–dek saklanmıştır
-- c001-v014: Peygamberlik–etti –ve da bunlara yedinci –den Adem'den Hanok diyerek İşte geldi Rab –de kutsal on–binlerce O'nun
-- c001-v015: yapmak–için yargı karşı hepsine ve azarlamak–için hepsini – tanrısızları hakkında tüm – işlerinin tanrısızlığın onların – işledikleri ve hakkında tüm – sert–sözlerin – söyledikleri karşı O'na günahkarlar tanrısızlar
-- c001-v016: Bunlar –dırlar söylenenler şikayetçiler göre – arzularına onların yürüyenler ve – ağızları onların söyler büyük–sözler hayranlık–duyanlar kişilere çıkar uğruna
-- c001-v017: Siz –ise sevgililer hatırlayın – sözlerini – önceden–söylenmiş –tarafından – elçilerin – Rab'bin bizim İsa Mesih'in
-- c001-v018: ki söylüyorlardı size – –de son – zamanda olacaklar alaycılar göre – kendi arzularına yürüyenler – tanrısızlıkların
-- c001-v019: Bunlar –dırlar – bölünme–yaratanlar nefsaniler Ruh'a – sahip–olmayanlar
-- c001-v020: siz –ise sevgililer inşa–ederek kendinizi – en–kutsal sizin imanınız–üzerine –de Ruh'ta Kutsal dua–ederek
-- c001-v021: kendinizi –de sevgisinde Tanrı'nın koruyun bekleyerek – merhametini – Rab'bin bizim İsa Mesih'in –e yaşama ebedi
-- c001-v022: ve –lere –bir–yandan merhamet–edin şüphe–edenlere
-- c001-v023: –leri –öte–yandan kurtarın –den ateşten kaparak –lere –ve merhamet–edin –de korkuyla nefret–ederek – – –den – beden–tarafından lekelenmiş giysiden–bile
-- c001-v024: –e –ise güçlü–olana korumaya sizi düşmekten ve dikmeye önünde – yüceliğinin O'nun kusursuz –de sevinçle
-- c001-v025: tek Tanrı'ya Kurtarıcımız bizim aracılığıyla İsa Mesih'in – Rab'bin bizim yücelik ululuk kudret ve yetki önce tüm – çağlardan ve şimdi ve –e tüm – çağlara amin

